html:
{%- set logs = frappe.get_all("Equipment Usage Log",
    filters={"job": doc.name},
    fields=["name","date","time_from","time_to","quantity","unit",
            "equipment","immatriculation","driver_operator","bon_prest",
            "bc_number","location","job_description","unit_price","amount",
            "comments"],
    order_by="date asc, time_from asc"
) -%}

{%- set client_name = doc.fetch_client or doc.client or "" -%}
{%- set file_no = doc.file_number or (doc.amt_job_file or "") -%}

<style>
  @page { margin: 10mm 8mm; size: A4 landscape; }
  body { font-family: Arial, sans-serif; font-size: 8pt; color: #000; }
  .header { margin-bottom: 8mm; }
  .header img { height: 18mm; }
  .header .title { font-size: 9pt; font-weight: bold; color: #1F3864; margin-top: 2mm; }
  .header .subtitle { font-size: 8pt; color: #555; }
  table { width: 100%; border-collapse: collapse; margin-top: 3mm; }
  th { background: #1F3864; color: #fff; padding: 3px 4px; text-align: center;
       font-size: 7.5pt; border: 0.5pt solid #fff; }
  td { padding: 2px 4px; border: 0.5pt solid #ccc; font-size: 7.5pt; }
  tr:nth-child(even) { background: #f5f6fa; }
  .date-total { background: #dde3ee; font-weight: bold; }
  .grand-total { background: #1F3864; color: #fff; font-weight: bold; font-size: 9pt; }
  .text-right { text-align: right; }
  .text-center { text-align: center; }
  .bold { font-weight: bold; }
</style>

<!-- HEADER -->
<div class="header">
  {% if letter_head %}{{ letter_head }}{% endif %}
  <div class="title">YARD ACTIVITIES / {{ client_name }}</div>
</div>

<!-- TABLE -->
<table>
  <thead>
    <tr>
      <th>CLIENT</th>
      <th>VEHICULE</th>
      <th>LOG MAT</th>
      <th>BON PREST</th>
      <th>FILE N°</th>
      <th>DATE</th>
      <th>FROM</th>
      <th>TO</th>
      <th>DUREE</th>
      <th>LOCATION</th>
      <th>JOB</th>
      <th>UNIT PRICE</th>
      <th>TOTAL HT</th>
    </tr>
  </thead>
  <tbody>
  {%- set ns = namespace(current_date="", date_total=0, grand_total=0, grand_qty=0, date_qty=0) -%}
  {%- for log in logs -%}
    {%- set log_date = frappe.format(log.date, {"fieldtype":"Date"}) -%}

    {%- if ns.current_date and log_date != ns.current_date -%}
    <!-- Date subtotal -->
    <tr class="date-total">
      <td colspan="8" class="text-right bold">Total {{ ns.current_date }}</td>
      <td class="text-center bold">{{ ns.date_qty }}</td>
      <td colspan="3"></td>
      <td class="text-right bold">{{ "{:,.0f}".format(ns.date_total) }}</td>
    </tr>
    {%- set ns.date_total = 0 -%}
    {%- set ns.date_qty = 0 -%}
    {%- endif -%}

    {%- set ns.current_date = log_date -%}
    {%- set ns.date_total = ns.date_total + (log.amount or 0) -%}
    {%- set ns.date_qty = ns.date_qty + (log.quantity or 0) -%}
    {%- set ns.grand_total = ns.grand_total + (log.amount or 0) -%}
    {%- set ns.grand_qty = ns.grand_qty + (log.quantity or 0) -%}

    <tr>
      <td>{{ client_name }}</td>
      <td>{{ log.immatriculation or "" }}</td>
      <td>{{ log.unit or "" }}</td>
      <td>{{ log.bon_prest or "" }}</td>
      <td>{{ file_no }}</td>
      <td class="text-center">{{ log_date }}</td>
      <td class="text-center">{{ log.time_from or "" }}</td>
      <td class="text-center">{{ log.time_to or "" }}</td>
      <td class="text-center">{{ log.quantity or "" }}</td>
      <td>{{ log.location or "" }}</td>
      <td>{{ log.job_description or log.comments or "" }}</td>
      <td class="text-right">{{ "{:,.0f}".format(log.unit_price or 0) }}</td>
      <td class="text-right">{{ "{:,.0f}".format(log.amount or 0) }}</td>
    </tr>
  {%- endfor -%}

  <!-- Last date subtotal -->
  {%- if ns.current_date -%}
  <tr class="date-total">
    <td colspan="8" class="text-right bold">Total {{ ns.current_date }}</td>
    <td class="text-center bold">{{ ns.date_qty }}</td>
    <td colspan="3"></td>
    <td class="text-right bold">{{ "{:,.0f}".format(ns.date_total) }}</td>
  </tr>
  {%- endif -%}

  <!-- Grand total -->
  <tr class="grand-total">
    <td colspan="7" class="text-right">Total général</td>
    <td></td>
    <td class="text-center">{{ ns.grand_qty }}</td>
    <td colspan="3"></td>
    <td class="text-right">{{ "{:,.0f}".format(ns.grand_total) }}</td>
  </tr>
  </tbody>
</table>

<!-- SIGNATURE BLOCK -->
<div style="margin-top:15mm;display:flex;justify-content:space-between;">
  <div style="text-align:center;width:40%;">
    <div style="border-top:1pt solid #000;padding-top:3mm;font-size:8pt;">
      AMT CAMEROUN S.A.<br>Logistics Coordinator
    </div>
  </div>
  <div style="text-align:center;width:40%;">
    <div style="border-top:1pt solid #000;padding-top:3mm;font-size:8pt;">
      {{ client_name }}<br>Client Representative
    </div>
  </div>
</div>
